SELECT

FROM inquiries i
JOIN users u ON u.id = i.user_id
LEFT JOIN inquiry_answers ia ON ia.inquiry_id = i.id
WHERE i.id = #{id}
  AND i.user_id = #{userId}

SELECT id, subject, content, status, created_at, updated_at, user_id, inquiry_type
FROM inquiries
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'PENDING'

