SELECT i.id, i.subject, i.status, i.inquiry_type, i.created_at, i.user_id, COALESCE(NULLIF(u.nickname, ''), u.username) AS user_display_name FROM inquiries i JOIN users u ON u.id = i.user_id
WHERE i.status = #{status}
ORDER BY i.created_at DESC, i.id DESC LIMIT #{limit} OFFSET #{offset}

